package com.example.loyalty.application.service;

import com.example.loyalty.application.dto.LoyaltyDtos.*;
import com.example.loyalty.application.port.*;
import com.example.loyalty.domain.model.*;
import com.example.loyalty.domain.service.*;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Duration;
import java.time.OffsetDateTime;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.UUID;
import java.util.stream.Collectors;

@Service
public class LoyaltyFacade {
    private final CustomerQueryService customerQueryService; private final LoyaltyAccountRepository accounts; private final RewardTransactionRepository transactions; private final OfferRepository offers; private final ClaimedOfferRepository claimedOffers; private final OfferStrategyFactory strategies; private final PurchaseInsightService purchaseInsights; private final JdbcTemplate jdbcTemplate;
    public LoyaltyFacade(CustomerQueryService customerQueryService, LoyaltyAccountRepository accounts, RewardTransactionRepository transactions, OfferRepository offers, ClaimedOfferRepository claimedOffers, OfferStrategyFactory strategies, PurchaseInsightService purchaseInsights, JdbcTemplate jdbcTemplate) { this.customerQueryService = customerQueryService; this.accounts = accounts; this.transactions = transactions; this.offers = offers; this.claimedOffers = claimedOffers; this.strategies = strategies; this.purchaseInsights = purchaseInsights; this.jdbcTemplate = jdbcTemplate; }
    @Transactional(readOnly = true) public BalanceDto balance(String email) { Customer customer = customerQueryService.requireByEmail(email); LoyaltyAccount account = accounts.findByCustomer(customer).orElseThrow(() -> new NotFoundException("Loyalty account not found")); return new BalanceDto(customer.getId(), account.getPointsBalance(), customer.getSegment()); }
    @Transactional(readOnly = true) public List<OfferDto> personalizedOffers(String email) { Customer customer = customerQueryService.requireByEmail(email); var profile = purchaseInsights.profile(customer); List<Offer> ranked = offers.findByStatus(OfferStatus.ACTIVE).stream().sorted((left, right) -> Integer.compare(offerScore(customer, profile, right), offerScore(customer, profile, left))).toList(); List<Offer> diversified = new ArrayList<>(); ranked.stream().collect(Collectors.groupingBy(Offer::getTargetCategory, java.util.LinkedHashMap::new, Collectors.toList())).values().forEach(group -> diversified.add(group.getFirst())); ranked.stream().filter(offer -> !diversified.contains(offer)).forEach(diversified::add); return diversified.stream().map(offer -> toOfferDto(customer, profile, offer)).toList(); }
    @Transactional public OfferDto claim(String email, Long offerId) { Customer customer = customerQueryService.requireByEmail(email); Offer offer = offers.findById(offerId).orElseThrow(() -> new NotFoundException("Offer not found")); var profile = purchaseInsights.profile(customer); String lifecycle = offerLifecycle(customer.getId(), offer.getId()); if ("CLAIMED".equals(lifecycle)) { Mission mission = missionFor(profile, offer); if (mission.progressPercent() < 100) throw new BusinessRuleViolationException("Mission is not completed yet"); LoyaltyAccount account = accounts.findByCustomer(customer).orElseThrow(() -> new NotFoundException("Loyalty account not found")); account.earn(offer.getBonusPoints()); transactions.save(new RewardTransaction(account, RewardTransactionType.EARN, offer.getBonusPoints(), "Mission completed: " + offer.getTitle())); jdbcTemplate.update("update claimed_offers set status = 'USED', used_at = now() where customer_id = ? and offer_id = ?", customer.getId(), offer.getId()); return toOfferDto(customer, profile, offer); } if (!"AVAILABLE".equals(lifecycle)) throw new BusinessRuleViolationException("Offer already used"); claimedOffers.save(new ClaimedOffer(customer, offer)); return toOfferDto(customer, profile, offer); }
    @Transactional public OfferDto completeOffer(String email, Long offerId) { Customer customer = customerQueryService.requireByEmail(email); Offer offer = offers.findById(offerId).orElseThrow(() -> new NotFoundException("Offer not found")); var profile = purchaseInsights.profile(customer); String lifecycle = offerLifecycle(customer.getId(), offerId); Mission mission = missionFor(profile, offer); if (!"CLAIMED".equals(lifecycle)) throw new BusinessRuleViolationException("Mission must be accepted first"); if (mission.progressPercent() < 100) throw new BusinessRuleViolationException("Mission target is not completed yet"); LoyaltyAccount account = accounts.findByCustomer(customer).orElseThrow(() -> new NotFoundException("Loyalty account not found")); account.earn(offer.getBonusPoints()); transactions.save(new RewardTransaction(account, RewardTransactionType.EARN, offer.getBonusPoints(), "Mission completed: " + offer.getTitle())); jdbcTemplate.update("update claimed_offers set status = 'USED', used_at = now() where customer_id = ? and offer_id = ?", customer.getId(), offerId); return toOfferDto(customer, profile, offer); }
    @Transactional public RedemptionDto redeem(String email, RedemptionRequest request) { Customer customer = customerQueryService.requireByEmail(email); LoyaltyAccount account = accounts.findByCustomer(customer).orElseThrow(() -> new NotFoundException("Loyalty account not found")); if (account.getPointsBalance() < request.points()) throw new BusinessRuleViolationException("Not enough points"); var profile = purchaseInsights.profile(customer); String category = request.targetCategory() == null || request.targetCategory().isBlank() ? purchaseInsights.recommendedCertificateCategory(profile) : request.targetCategory(); BigDecimal discount = BigDecimal.valueOf(request.points()).divide(BigDecimal.TEN); String code = "LP-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase(); account.redeem(request.points()); transactions.save(new RewardTransaction(account, RewardTransactionType.REDEEM, -request.points(), "Redeemed for " + request.rewardName() + " (" + category + ")")); jdbcTemplate.update("insert into redemption_orders(customer_id, account_id, points_spent, discount_amount, reward_name, confirmation_code, target_category) values (?, ?, ?, ?, ?, ?, ?)", customer.getId(), account.getId(), request.points(), discount, request.rewardName(), code, category); return new RedemptionDto(request.points(), discount, account.getPointsBalance(), code, request.rewardName(), category, purchaseInsights.certificateReason(profile, category)); }
    @Transactional(readOnly = true) public List<CertificateDto> certificates(String email) { Customer customer = customerQueryService.requireByEmail(email); return jdbcTemplate.query("""
        select id, points_spent, discount_amount, reward_name, confirmation_code, status, created_at, expires_at, used_at, purchase_id, target_category
        from redemption_orders
        where customer_id = ?
        order by created_at desc
        """, (rs, rowNum) -> new CertificateDto(rs.getLong("id"), rs.getInt("points_spent"), rs.getBigDecimal("discount_amount"), rs.getString("reward_name"), rs.getString("confirmation_code"), rs.getString("target_category"), rs.getString("status"), rs.getObject("created_at", java.time.OffsetDateTime.class), rs.getObject("expires_at", java.time.OffsetDateTime.class), rs.getObject("used_at", java.time.OffsetDateTime.class), (Long) rs.getObject("purchase_id")), customer.getId()); }
    @Transactional public CustomerSegment recalculateSegment(String email) { Customer customer = customerQueryService.requireByEmail(email); java.math.BigDecimal total = jdbcTemplate.queryForObject("select coalesce(sum(total_amount),0) from purchases where customer_id = ?", java.math.BigDecimal.class, customer.getId()); int spent = total == null ? 0 : total.intValue(); customer.setSegment(spent > 700 ? CustomerSegment.PREMIUM : spent > 150 ? CustomerSegment.REGULAR : CustomerSegment.NEWCOMER); return customer.getSegment(); }
    @Transactional(readOnly = true) public Page<RewardTransactionDto> transactions(String email, Pageable pageable) { Customer customer = customerQueryService.requireByEmail(email); LoyaltyAccount account = accounts.findByCustomer(customer).orElseThrow(() -> new NotFoundException("Loyalty account not found")); return transactions.findByAccount(account, pageable).map(tx -> new RewardTransactionDto(tx.getId(), tx.getType(), tx.getPoints(), tx.getReason(), tx.getCreatedAt())); }
    @Transactional(readOnly = true) public PurchaseProfileDto purchaseProfile(String email) { Customer customer = customerQueryService.requireByEmail(email); var profile = purchaseInsights.profile(customer); return new PurchaseProfileDto(profile.categories().stream().map(category -> new CategoryInsightDto(category.category(), category.purchaseCount(), category.spent(), purchaseInsights.sharePercent(profile, category), category.lastPurchaseAt() == null ? null : category.lastPurchaseAt().toString(), purchaseInsights.categoryAverageCheck(category))).toList(), profile.purchaseCount(), profile.totalSpent(), profile.lastPurchaseAt() == null ? null : profile.lastPurchaseAt().toString(), purchaseInsights.averageCheck(profile), purchaseInsights.frequencyLabel(profile), purchaseInsights.buyerRating(profile), purchaseInsights.buyerRatingLabel(profile)); }
    @Cacheable("loyaltyProgram")
    @Transactional(readOnly = true) public LoyaltyProgramDto program() { List<RewardRuleDto> rewardRules = jdbcTemplate.query("select code as category, cashback_percent, description from product_categories where active = true order by cashback_percent desc", (rs, rowNum) -> new RewardRuleDto(rs.getString("category"), rs.getBigDecimal("cashback_percent"), rs.getString("description"))); List<SegmentRuleDto> segmentRules = jdbcTemplate.query("select segment, min_total_spend, multiplier, description from customer_segment_thresholds order by min_total_spend", (rs, rowNum) -> new SegmentRuleDto(CustomerSegment.valueOf(rs.getString("segment")), rs.getBigDecimal("min_total_spend"), rs.getBigDecimal("multiplier"), rs.getString("description"))); return new LoyaltyProgramDto(rewardRules, segmentRules, "10 points = 1 discount currency unit. Minimum redemption is 50 points."); }
    private OfferDto toOfferDto(Customer customer, PurchaseInsightService.PurchaseProfile profile, Offer offer) { String lifecycle = offerLifecycle(customer.getId(), offer.getId()); Mission mission = missionFor(profile, offer); int visibleProgress = "USED".equals(lifecycle) ? 100 : mission.progressPercent(); String nextStep = switch (lifecycle) { case "CLAIMED" -> visibleProgress >= 100 ? "Цель выполнена. Нажмите «Активировать бонус», чтобы начислить +" + offer.getBonusPoints() + " баллов." : "Задание активно: " + mission.conditionSummary() + ". Прогресс сейчас " + visibleProgress + "%."; case "USED" -> "Задание выполнено, бонус уже начислен. Следующее задание появится по новой истории покупок."; default -> purchaseInsights.buyerRating(profile) >= mission.requiredRating() ? "Можно принять задание: " + mission.conditionSummary() + "." : "Пока заблокировано: нужен рейтинг покупателя " + mission.requiredRating() + "+. Делайте покупки и повышайте активность."; }; return new OfferDto(offer.getId(), offer.getTitle(), offer.getDescription(), offer.getTargetCategory(), offer.getBonusPoints(), offer.getValidUntil(), offerScore(customer, profile, offer), purchaseInsights.explanation(profile, offer.getTargetCategory()), lifecycle, nextStep, mission.type(), mission.title(), mission.conditionSummary(), mission.difficulty(), mission.metricLabel(), mission.baselineValue(), mission.targetValue(), mission.currentValue(), visibleProgress, mission.requiredRating(), mission.businessGoal()); }
    private int offerScore(Customer customer, PurchaseInsightService.PurchaseProfile profile, Offer offer) { return strategies.combinedScore(customer, offer) + purchaseInsights.historyScore(profile, offer.getTargetCategory()); }
    private String offerLifecycle(Long customerId, Long offerId) { return jdbcTemplate.query("select status from claimed_offers where customer_id = ? and offer_id = ?", rs -> rs.next() ? rs.getString("status") : "AVAILABLE", customerId, offerId); }
    private Mission missionFor(PurchaseInsightService.PurchaseProfile profile, Offer offer) { PurchaseInsightService.CategoryStat stat = profile.categories().stream().filter(category -> category.category().equals(offer.getTargetCategory())).findFirst().orElse(new PurchaseInsightService.CategoryStat(offer.getTargetCategory(), 0, BigDecimal.ZERO, null)); BigDecimal avg = purchaseInsights.averageCheck(profile); BigDecimal categoryAvg = purchaseInsights.categoryAverageCheck(stat); int rating = purchaseInsights.buyerRating(profile); BigDecimal categoryMultiplier = categoryMissionMultiplier(offer.getTargetCategory()); int adjustedBonus = BigDecimal.valueOf(offer.getBonusPoints()).multiply(categoryMultiplier).setScale(0, RoundingMode.HALF_UP).intValue(); if (adjustedBonus >= 240) { BigDecimal target = BigDecimal.valueOf(100); int countProgress = Math.min(100, stat.purchaseCount() * 50); BigDecimal avgTarget = avg.multiply(BigDecimal.valueOf(1.15)).setScale(2, RoundingMode.HALF_UP); int avgProgress = avgTarget.compareTo(BigDecimal.ZERO) == 0 ? 0 : categoryAvg.multiply(BigDecimal.valueOf(100)).divide(avgTarget, 0, RoundingMode.HALF_UP).min(BigDecimal.valueOf(100)).intValue(); int progress = (countProgress + avgProgress) / 2; return new Mission("MULTI_CONDITION", "Сделайте 2 покупки и поднимите чек", "совершите 2 покупки в " + offer.getTargetCategory() + " и держите средний чек от " + avgTarget.intValue() + " ₽", "HARD", "общий прогресс", BigDecimal.ZERO, target, BigDecimal.valueOf(progress), progress, 70, "Увеличить частоту и средний чек в категории " + offer.getTargetCategory()); } if (stat.purchaseCount() == 0 || purchaseInsights.sharePercent(profile, stat).compareTo(BigDecimal.valueOf(15)) < 0) { int targetPurchases = stat.purchaseCount() + 2; int progress = Math.min(100, BigDecimal.valueOf(stat.purchaseCount()).multiply(BigDecimal.valueOf(100)).divide(BigDecimal.valueOf(targetPurchases), 0, RoundingMode.HALF_UP).intValue()); return new Mission("PURCHASE_COUNT", "Откройте новую категорию", "сделайте " + targetPurchases + " покупки в " + offer.getTargetCategory(), "MEDIUM", "покупки", BigDecimal.valueOf(stat.purchaseCount()), BigDecimal.valueOf(targetPurchases), BigDecimal.valueOf(stat.purchaseCount()), progress, 35, "Развить недопокупаемую категорию " + offer.getTargetCategory()); } if (stat.lastPurchaseAt() != null && Duration.between(stat.lastPurchaseAt(), OffsetDateTime.now()).toDays() > 14) { BigDecimal days = BigDecimal.valueOf(Duration.between(stat.lastPurchaseAt(), OffsetDateTime.now()).toDays()); int progress = days.compareTo(BigDecimal.ZERO) == 0 ? 100 : BigDecimal.valueOf(7).multiply(BigDecimal.valueOf(100)).divide(days, 0, RoundingMode.HALF_UP).min(BigDecimal.valueOf(100)).intValue(); return new Mission("FREQUENCY_RETURN", "Вернитесь в категорию", "сделайте покупку в " + offer.getTargetCategory() + " в течение 7 дней", "EASY", "дней с покупки", days, BigDecimal.valueOf(7), days, progress, 20, "Вернуть клиента в категорию после паузы"); } BigDecimal target = avg.multiply(BigDecimal.valueOf(1.2)).setScale(2, RoundingMode.HALF_UP); int progress = target.compareTo(BigDecimal.ZERO) == 0 ? 0 : categoryAvg.multiply(BigDecimal.valueOf(100)).divide(target, 0, RoundingMode.HALF_UP).min(BigDecimal.valueOf(100)).intValue(); int required = adjustedBonus >= 200 ? 55 : 30; return new Mission("AVERAGE_CHECK_GROWTH", "Увеличьте средний чек", "увеличьте средний чек в " + offer.getTargetCategory() + " до " + target.intValue() + " ₽", adjustedBonus >= 200 ? "MEDIUM" : "EASY", "средний чек", avg, target, categoryAvg, progress, Math.min(required, Math.max(20, rating - 10)), "Увеличить средний чек в категории " + offer.getTargetCategory()); }
    private BigDecimal categoryMissionMultiplier(String category) { return jdbcTemplate.query("select mission_multiplier from product_categories where code = ?", rs -> rs.next() ? rs.getBigDecimal(1) : BigDecimal.ONE, category); }
    private record Mission(String type, String title, String conditionSummary, String difficulty, String metricLabel, BigDecimal baselineValue, BigDecimal targetValue, BigDecimal currentValue, int progressPercent, int requiredRating, String businessGoal) {}
}
